window.MUSEUM_CALENDAR={"dated":true,"01-01":{"t":"Обзор краёв — Север, юг, средняя полоса, Дон, Сибирь","d":"Крестьянка выходила из избы в понёве и сороке, и любой встречный читал по ним край, возраст и замужество без единого слова.","href":"/muzei/narodnyy-kostyum/den/01-01/"},"01-02":{"t":"Пошехонье — Пошехонский уезд Ярославской губ.","d":"Пошехонье, которое острословы сделали словом для глуши, на праздник выходило в шёлковых сарафанах и шитых кокошниках.","href":"/muzei/narodnyy-kostyum/den/01-02/"},"01-03":{"t":"Кемь, Поморский берег — Кемский уезд Архангельской губ.","d":"Помор уходил на Мурман в рокане, пропитанном ворванью, и эта куртка держала ледяную волну всю весеннюю путину.","href":"/muzei/narodnyy-kostyum/den/01-03/"},"01-04":{"t":"Торжок, золотное шитьё — Новоторжский уезд Тверской губ.","d":"Торжокские золотошвеи шили кокошники и сафьяновые сапожки золотой нитью, и фабрика в Торжке держит это ремесло до сих пор.","href":"/muzei/narodnyy-kostyum/den/01-04/"},"01-05":{"t":"Старочеркасская — Область Войска Донского","d":"Донской казак шил шаровары с красным лампасом, и эту алую полосу Дон пронёс от царских смотров до сегодняшних парадов.","href":"/muzei/narodnyy-kostyum/den/01-05/"},"01-06":{"t":"Полтавская губ., Святвечер — сёла Полтавщины","d":"Полтавская молодица встречала Святвечер в очипке, керсетке и красных чоботах, и этот наряд колядки проносят по сёлам до сих пор.","href":"/muzei/narodnyy-kostyum/den/01-06/"},"01-07":{"t":"Курская губ., Святки — сёла Курской губ.","d":"Курские ребятишки в вывороченных тулупах обходили дворы на Рождество, и хозяйки платили им пирогами за каждую колядку.","href":"/muzei/narodnyy-kostyum/den/01-07/"},"01-08":{"t":"Михайловский уезд — Рязанская губ.","d":"Священники гнали молодух в рогатых кичках из церкви, а михайловские бабы так и носили рога на голове до самого XX века.","href":"/muzei/narodnyy-kostyum/den/01-08/"},"01-09":{"t":"Заонежье — Петрозаводский уезд Олонецкой губ.","d":"Заонежская невеста снимала девичью повязку под причеты, и плачи вопленицы Ирины Федосовой Барсов издал отдельной книгой.","href":"/muzei/narodnyy-kostyum/den/01-09/"},"01-10":{"t":"Бежецк — Бежецкий уезд Тверской губ.","d":"Бежецкие девки пряли на зимних посиделках в лучших сарафанах, потому что туда приходили парни присматривать невест.","href":"/muzei/narodnyy-kostyum/den/01-10/"},"01-11":{"t":"Шуя, «парочка» — Шуйский уезд Владимирской губ.","d":"Фабричный ситец дал деревне кофту и юбку «парочку», и к 1900-м она сняла с девок сарафан быстрее любого указа.","href":"/muzei/narodnyy-kostyum/den/01-11/"},"01-12":{"t":"Москва, 1867 — Этнографическая выставка в Манеже","d":"В 1867 году в московском Манеже встали манекены в подлинных крестьянских нарядах, и эти костюмы легли в основу Дашковского музея.","href":"/muzei/narodnyy-kostyum/den/01-12/"},"01-13":{"t":"Зарайск — Зарайский уезд Рязанской губ.","d":"Зарайский мужик опоясывал праздничный кафтан тканым кушаком, и без кушака его в селе считали попросту неодетым.","href":"/muzei/narodnyy-kostyum/den/01-13/"},"01-14":{"t":"Москва — указ о платье 1700","d":"Пётр I указом 14 января 1700 года велел сменить русское платье на венгерское, а деревня свою рубаху и сарафан так и не сняла.","href":"/muzei/narodnyy-kostyum/den/01-14/"},"01-15":{"t":"Замоскворечье — Москва","d":"Замоскворецкая купчиха шла к обедне в лисьей шубе и набивной шали, и Островский списывал таких с натуры для своих пьес.","href":"/muzei/narodnyy-kostyum/den/01-15/"},"01-16":{"t":"Москва, указ о бороде — указ 1705","d":"Указом 16 января 1705 года Пётр обложил бороду пошлиной, и купцы платили, но с бородой так и не расстались.","href":"/muzei/narodnyy-kostyum/den/01-16/"},"01-17":{"t":"Полтавская губ. — сёла Полтавщины","d":"Полтавская дивчина носила венок с лентами до самой свадьбы, и вышитые плахты с венками дожили в сундуках сёл до музеев.","href":"/muzei/narodnyy-kostyum/den/01-17/"},"01-18":{"t":"Гороховец — Гороховецкий уезд Владимирской губ.","d":"Новорождённого во Владимирской губернии заворачивали в ношеную отцовскую рубаху, и она служила ему первым оберегом.","href":"/muzei/narodnyy-kostyum/den/01-18/"},"01-19":{"t":"Тверская губ., Крещение — сёла Тверской губ.","d":"На Крещение тверские мужики в тулупах вырубали во льду иордань, и купание в проруби дожило до сегодняшних январей.","href":"/muzei/narodnyy-kostyum/den/01-19/"},"01-20":{"t":"Новгород — раскопки Неревского и других концов","d":"Новгородская земля сохранила тысячи кожаных сапог XI–XV веков, а берестяные грамоты донесли, кто кому шил и продавал платье.","href":"/muzei/narodnyy-kostyum/den/01-20/"},"01-21":{"t":"Зимний дворец, 1903 — костюмированный бал","d":"На балу 1903 года Николай II вышел в платне царя Алексея Михайловича, и снимки тех нарядов разошлись по России открытками.","href":"/muzei/narodnyy-kostyum/den/01-21/"},"01-22":{"t":"Ростов Великий — сёла Ростовского уезда Ярославской губ.","d":"Ростовские огородники развозили зелень по всей России, и их жёны наряжались в фабричный шёлк раньше соседних деревень.","href":"/muzei/narodnyy-kostyum/den/01-22/"},"01-23":{"t":"Терский берег — Варзуга, Умба","d":"Терские поморки низали кокошники речным жемчугом северных рек, и такие уборы передавали в семье через поколения.","href":"/muzei/narodnyy-kostyum/den/01-23/"},"01-24":{"t":"Вологда, кружево — Вологодский уезд","d":"Вологодская кружевница вела по подушке десятки коклюшек, и её парный приём плетения живёт в Вологде до сих пор.","href":"/muzei/narodnyy-kostyum/den/01-24/"},"01-25":{"t":"Дон, казачки — станицы Области Войска Донского","d":"Донская казачка застёгивала кубелёк на серебряные пуговицы, и этот распашной наряд шьют на Дону и сегодня.","href":"/muzei/narodnyy-kostyum/den/01-25/"},"01-26":{"t":"Скопин — Скопинский уезд Рязанской губ.","d":"Скопинская понёва по клетке и прошве выдавала село хозяйки, и рязанские собиратели сохранили такие понёвы десятками.","href":"/muzei/narodnyy-kostyum/den/01-26/"},"01-27":{"t":"Тульская губ., Одоевский уезд — южнорусская свадьба","d":"Наутро после свадьбы одоевской молодухе надевали кичку с понёвой, и девичью косу с этого дня на людях уже никто не видел.","href":"/muzei/narodnyy-kostyum/den/01-27/"},"01-28":{"t":"Вологодская губ., лесоповал — лесные уезды Вологодской губ.","d":"Вологодские лесорубы валили лес в лаптях с онучами и голицах поверх вязаных варежек, и вывозили брёвна по зимнику до весны.","href":"/muzei/narodnyy-kostyum/den/01-28/"},"01-29":{"t":"Иваново, 1920-е — красная косынка вместо кокошника","d":"В 1920-е ивановские ткачихи сменили кокошник на красную косынку, и ситец своих фабрик понесли в новую моду страны.","href":"/muzei/narodnyy-kostyum/den/01-29/"},"01-30":{"t":"Абрамцево, Мамонтовы — «Снегурочка» 1882 и собрание крестьянской одежды","d":"Васнецов в 1882 году одел домашнюю «Снегурочку» Мамонтовых в крестьянские наряды, и с тех пор Снегурочка ходит в кокошнике.","href":"/muzei/narodnyy-kostyum/den/01-30/"},"01-31":{"t":"Углич — Угличский уезд Ярославской губ.","d":"Угличские крестьянки шили праздничные сарафаны из покупной парчи, и такие наряды хранит музей города до сих пор.","href":"/muzei/narodnyy-kostyum/den/01-31/"},"02-01":{"t":"Кологрив — плотники-отходники","d":"Кологривский плотник возвращался из Питера в суконной поддёвке и сапогах, и деревня по одной одежде видела, что отход удался.","href":"/muzei/narodnyy-kostyum/den/02-01/"},"02-02":{"t":"Каргополь, зима — Каргопольский уезд Олонецкой губ.","d":"Каргопольская девушка выходила на зимнее гулянье в шубке, крытой ярким штофом, и деревня видела её праздничный цвет сквозь снег.","href":"/muzei/narodnyy-kostyum/den/02-02/"},"02-03":{"t":"Калуга — мещане уездного города","d":"Калужская мещанка сменила сарафан на «парочку» — кофту с юбкой, и уездный город по одежде отделил себя от деревни.","href":"/muzei/narodnyy-kostyum/den/02-03/"},"02-04":{"t":"Черниговская губ. — намитка и вышитая сорочка","d":"Черниговская молодица после венчания навсегда покрывала волосы белой намиткой, и полотно на голове говорило селу о её замужестве.","href":"/muzei/narodnyy-kostyum/den/02-04/"},"02-05":{"t":"Елец, кружево — Елецкий уезд Орловской губ.","d":"Елецкая кружевница обшивала коклюшечным кружевом рукава и передник, и простая холщовая рубаха становилась праздничной.","href":"/muzei/narodnyy-kostyum/den/02-05/"},"02-06":{"t":"Дон, проводы — станицы Области Войска Донского","d":"Донская казачка провожала сына на службу в праздничном кубелёке и шлычке, а сын уходил в справе, купленной на семейные деньги.","href":"/muzei/narodnyy-kostyum/den/02-06/"},"02-07":{"t":"Вологодская губ. — крестильная рубашка","d":"Вологодская крёстная шила младенцу крестильную рубашку, и семья берегла её в сундуке как оберег на всю жизнь крестника.","href":"/muzei/narodnyy-kostyum/den/02-07/"},"02-08":{"t":"Сапожок — девичий наряд «на выданье»","d":"Сапожковская девушка впервые надевала понёву и считалась невестой, и с этого дня женихи видели её зрелость по клетке подола.","href":"/muzei/narodnyy-kostyum/den/02-08/"},"02-09":{"t":"Вологодская губ. — девичник и свадебная баня","d":"Вологодская невеста на девичнике снимала девичью «красоту» перед подругами, и лента с её косы уходила к младшей сестре.","href":"/muzei/narodnyy-kostyum/den/02-09/"},"02-10":{"t":"Романов-Борисоглебск — романовская овчина и шубы","d":"Романовские овцы давали лёгкую тёплую овчину, и полушубки из Романова-Борисоглебска носили по всей России.","href":"/muzei/narodnyy-kostyum/den/02-10/"},"02-11":{"t":"Семёнов, валенки — Семёновский уезд Нижегородской губ.","d":"Семёновские пимокаты валяли сапог без единого шва из одной шерсти, и в таких катанках крестьянин переходил зиму по снегу.","href":"/muzei/narodnyy-kostyum/den/02-11/"},"02-12":{"t":"Никольск — зимняя одежда лесного края","d":"Никольский лесоруб уходил на зимнюю делянку в шабуре поверх овчины, и сукно держало снег, а мех держал тепло.","href":"/muzei/narodnyy-kostyum/den/02-12/"},"02-13":{"t":"Старая Ладога — одежда по раскопкам","d":"В сыром ладожском слое пролежали тысячу лет кожаные башмаки и обрывки сукна, и по ним видно, как одевались первые жители.","href":"/muzei/narodnyy-kostyum/den/02-13/"},"02-14":{"t":"Петербург, двор 1834 — указ о «русском платье» придворных дам","d":"Николай I в 1834 году одел придворных дам в бархатное «русское платье» с кокошником, и оно продержалось при дворе до 1917 года.","href":"/muzei/narodnyy-kostyum/den/02-14/"},"02-15":{"t":"Урал, 1941 — ватник и телогрейка в тылу","d":"Уральская работница стояла у станка в стёганой телогрейке, и ватник военной зимы стал одеждой целой страны.","href":"/muzei/narodnyy-kostyum/den/02-15/"},"02-16":{"t":"Петербург, 1902 — Этнографический отдел Русского музея (ныне РЭМ)","d":"В 1902 году при Русском музее открыли Этнографический отдел, и сундуки с деревенской одеждой стали музейным фондом.","href":"/muzei/narodnyy-kostyum/den/02-16/"},"02-17":{"t":"Валдай — ямщики: дорожная мужская одежда","d":"Валдайский ямщик туго затягивал армяк цветным кушаком и надевал низкую шляпу, и его узнавали на тракте издали.","href":"/muzei/narodnyy-kostyum/den/02-17/"},"02-18":{"t":"Павловский Посад — набивной шерстяной платок","d":"Павлово-посадская мануфактура с 1860-х набивала шерстяные платки досками, и цветастый полушалок дожил до наших дней на той же фабрике.","href":"/muzei/narodnyy-kostyum/den/02-18/"},"02-19":{"t":"Терек, поход — бурка и башлык в зимнем походе","d":"Терский казак в зимнем походе укрывался буркой от метели, а башлык заворачивал на голове так, что снаружи оставались только глаза.","href":"/muzei/narodnyy-kostyum/den/02-19/"},"02-20":{"t":"Ирбит — Ирбитская ярмарка","d":"Ирбитская ярмарка зимой собирала купцов со всей России, и лисьи шубы с китайским шёлком расходились отсюда по Уралу и Сибири.","href":"/muzei/narodnyy-kostyum/den/02-20/"},"02-21":{"t":"Минусинск — старожилы Минусинской котловины","d":"Аптекарь Николай Мартьянов в 1877 году начал собирать в Минусинске вещи старожилов, и крестьянские кафтаны и сарафаны попали в один из старейших музеев Сибири.","href":"/muzei/narodnyy-kostyum/den/02-21/"},"02-22":{"t":"Черниговская губ., зима — кожух и свита","d":"Черниговский крестьянин носил суконную свиту поверх кожуха, и по крою и цвету свиты в селе знали, откуда он родом.","href":"/muzei/narodnyy-kostyum/den/02-22/"},"02-23":{"t":"Ефремов — будничная понёва и сорока","d":"Ефремовская баба носила будничную понёву каждый день до дыр, а праздничную сороку берегла и передавала дочери.","href":"/muzei/narodnyy-kostyum/den/02-23/"},"02-24":{"t":"Курская губ. — сватовство","d":"Курская невеста в знак согласия перевязывала сватов вышитыми полотенцами, и сватовство кончалось без единого слова.","href":"/muzei/narodnyy-kostyum/den/02-24/"},"02-25":{"t":"Мезень — зимняя промысловая одежда и праздничный сарафан","d":"Мезенская семья держала в одном доме оленью малицу для промысла и штофный сарафан для праздника, и обе вещи дошли до музеев.","href":"/muzei/narodnyy-kostyum/den/02-25/"},"02-26":{"t":"Тобольский тракт — санный путь: обоз, тулуп и доха","d":"На Тобольском тракте обозник надевал доху мехом наружу поверх тулупа и выдерживал сутки в санях на сибирском морозе.","href":"/muzei/narodnyy-kostyum/den/02-26/"},"02-27":{"t":"Вятская губ. — детская зимняя одежда","d":"Вятская мать перешивала детскую шубку из старого отцовского полушубка, и одна овчина согревала в семье трёх детей подряд.","href":"/muzei/narodnyy-kostyum/den/02-27/"},"02-28":{"t":"Кострома, набойка — Костромская губ.","d":"Костромской набойщик печатал белый узор на синем холсте манерой, и будничный сарафан выглядел как дорогая привозная ткань.","href":"/muzei/narodnyy-kostyum/den/02-28/"},"03-01":{"t":"Верхнедонские казаки — станица Вёшенская, Войско Донское","d":"Верхнедонской казак носил фуражку с красным околышем и лампасы на шароварах, и по ним в любой станице узнавали донца.","href":"/muzei/narodnyy-kostyum/den/03-01/"},"03-02":{"t":"Праздничный наряд льняного края — Кинешма, Костромская губ.","d":"Под Кинешмой лён сеяли, пряли и ткали в каждом доме, и праздничный сарафан начинался с собственной полосы на поле.","href":"/muzei/narodnyy-kostyum/den/03-02/"},"03-03":{"t":"Проводы на войну 1914 г. — Ржев, Тверская губ.","d":"Летом 1914 года ржевские новобранцы уходили на войну в лучших косоворотках, и семейные фотографии сохранили этот последний праздничный наряд.","href":"/muzei/narodnyy-kostyum/den/03-03/"},"03-04":{"t":"Собрание русского костюма Натальи Шабельской — северные и центральные губернии","d":"Наталья Шабельская годами скупала по деревням старинные кокошники и сарафаны, и её собрание показало русский убор Европе.","href":"/muzei/narodnyy-kostyum/den/03-04/"},"03-05":{"t":"Жемчужные кокошники — Онежский уезд, Архангельская губ.","d":"Онежская женщина берегла жемчужный кокошник всю жизнь и передавала его дочери, и убор пережил своих хозяек на целый век.","href":"/muzei/narodnyy-kostyum/den/03-05/"},"03-06":{"t":"Мужской праздничный костюм — Владимирская губ.","d":"Владимирский парень выходил на гулянье в синем кафтане и красной косоворотке, и наряд жениха видела вся улица.","href":"/muzei/narodnyy-kostyum/den/03-06/"},"03-07":{"t":"Праздничный наряд — Новосильский уезд, Тульская губ.","d":"Новосильская молодуха надевала тёмную клетчатую понёву с красной прошвой, и по клетке соседи узнавали её родное село.","href":"/muzei/narodnyy-kostyum/den/03-07/"},"03-08":{"t":"Масленица: молодожёны на катании — Ярославская губ.","d":"На Масленицу ярославских молодожёнов катали по селу в санях, и молодуха выезжала в лучшей шубке, чтобы её разглядела вся округа.","href":"/muzei/narodnyy-kostyum/den/03-08/"},"03-09":{"t":"Свадебный поезд — Тверская губ.","d":"Тверской дружка вёл свадебный поезд с вышитым полотенцем через плечо, и каждый встречный знал, кто здесь главный распорядитель.","href":"/muzei/narodnyy-kostyum/den/03-09/"},"03-10":{"t":"Фабричные рабочие — Иваново-Вознесенск, Владимирская губ.","d":"Ивановская ткачиха сменила понёву на ситцевую «парочку», и фабричный наряд к 1900 году дошёл до соседних деревень.","href":"/muzei/narodnyy-kostyum/den/03-10/"},"03-11":{"t":"Свадебный наряд — Киевская губ.","d":"Киевская невеста надевала венок с лентами последний раз в жизни, и после свадьбы его сменяла белая намитка замужней.","href":"/muzei/narodnyy-kostyum/den/03-11/"},"03-12":{"t":"Масленица: праздничный зимний наряд — Онега, Архангельская губ.","d":"На масленичных катаниях онежская молодуха выезжала в крытой штофом шубке, и из-под меха поблёскивал жемчуг кокошника.","href":"/muzei/narodnyy-kostyum/den/03-12/"},"03-13":{"t":"Рабочий сарафан и понёва хозяйки — Темниковский уезд, Тамбовская губ.","d":"Темниковская хозяйка носила будничную понёву до дыр, а праздничную берегла в сундуке и отдавала в приданое дочери.","href":"/muzei/narodnyy-kostyum/den/03-13/"},"03-14":{"t":"Масленичные балаганы — Адмиралтейская площадь, Петербург","d":"Балаганный дед зазывал публику на Адмиралтейской площади в рваном армяке с бородой из пакли, и вся масленичная толпа хохотала.","href":"/muzei/narodnyy-kostyum/den/03-14/"},"03-15":{"t":"Женский убор замужней — Галич, Костромская губ.","d":"Галичская молодуха после венца прятала волосы под повойник, и показать косу на людях стало для неё позором на всю жизнь.","href":"/muzei/narodnyy-kostyum/den/03-15/"},"03-16":{"t":"Курганный убор XII в. — земля вятичей, Подмосковье","d":"Вятичанка носила на висках семилопастные кольца, и по ним археологи через восемьсот лет очертили границы земли вятичей.","href":"/muzei/narodnyy-kostyum/den/03-16/"},"03-17":{"t":"Императрица в русском платье — Петербург, двор Екатерины II","d":"Екатерина II заказывала платья «в русском вкусе» с откидными рукавами, и придворные дамы повторяли за ней крестьянский шушун.","href":"/muzei/narodnyy-kostyum/den/03-17/"},"03-18":{"t":"Ситценабивные фабрики — Иваново","d":"Ивановские фабрики печатали ситец вёрстами, и к 1900 году крашенина в сундуках уступила место пёстрому набивному сарафану.","href":"/muzei/narodnyy-kostyum/den/03-18/"},"03-19":{"t":"Низовые казаки — станица Цимлянская, Войско Донское","d":"Низовая казачка застёгивала праздничный кубелёк на длинный ряд мелких пуговиц, и наряд продержался на Дону до двадцатого века.","href":"/muzei/narodnyy-kostyum/den/03-19/"},"03-20":{"t":"Праздничный комплекс — Каргополь, Олонецкая губ.","d":"Каргопольская молодуха надевала кокошник-сборник в жемчуге и золоте, и этот убор переходил по женской линии от бабки к внучке.","href":"/muzei/narodnyy-kostyum/den/03-20/"},"03-21":{"t":"Красная косынка — Москва, 1920-е","d":"Московская работница двадцатых сняла бабий платок и повязала красную косынку узлом на затылке, и косынка стала знаком новой женщины.","href":"/muzei/narodnyy-kostyum/den/03-21/"},"03-22":{"t":"Билибин на Севере — экспедиции по Вологодской, Олонецкой, Архангельской губ.","d":"Иван Билибин объездил северные губернии и зарисовал кокошники и сарафаны, которые потом ожили в его иллюстрациях к сказкам.","href":"/muzei/narodnyy-kostyum/den/03-22/"},"03-23":{"t":"Первая понёва — Спасский уезд, Рязанская губ.","d":"Рязанская девочка «вскакивала в понёву» прыжком с лавки, и с этого дня деревня считала её невестой.","href":"/muzei/narodnyy-kostyum/den/03-23/"},"03-24":{"t":"Праздничная понёва и шушпан — Обоянский уезд, Курская губ.","d":"Обоянская баба выходила на праздник в шушпане поверх красной понёвы, и курский наряд носили по сёлам ещё в 1920-х.","href":"/muzei/narodnyy-kostyum/den/03-24/"},"03-25":{"t":"Сибирская свадьба — Енисейская губ.","d":"Енисейская невеста ехала к венцу в шубе поверх штофного сарафана, и сибирский мороз не отменял ни одной свадебной вещи.","href":"/muzei/narodnyy-kostyum/den/03-25/"},"03-26":{"t":"Наряд льноткачей — Вязники, Владимирская губ.","d":"Вязниковские ткачи отправляли тонкое полотно на ярмарки, а себе шили рубахи из того же льна, только погрубее.","href":"/muzei/narodnyy-kostyum/den/03-26/"},"03-27":{"t":"Багренье уральских казаков — Уральск, Уральское казачье войско","d":"По пушечному выстрелу уральские казаки в тулупах и малахаях разом бросались с баграми на лёд Урала, и багренье дожило до XX века.","href":"/muzei/narodnyy-kostyum/den/03-27/"},"03-28":{"t":"Дорожный комплект — Калужская губ.","d":"Калужский мужик обматывал ноги онучами и затягивал оборы лаптей крест-накрест, и в таком комплекте проходил сотни вёрст.","href":"/muzei/narodnyy-kostyum/den/03-28/"},"03-29":{"t":"Браное ткачество — Архангельская губ.","d":"Северная ткачиха выбирала узор на станке нитка за ниткой, и браный подол рубахи переживал саму хозяйку.","href":"/muzei/narodnyy-kostyum/den/03-29/"},"03-30":{"t":"Черкеска и папаха — Кубанское казачье войско","d":"Кубанский казак перенял у горцев черкеску с газырями, и она стала парадной формой всего войска.","href":"/muzei/narodnyy-kostyum/den/03-30/"},"03-31":{"t":"Девичий праздничный наряд — Заонежье, Олонецкая губ. (Толвуя, Шуньга)","d":"Заонежская девушка шла на Шуньгскую ярмарку в жемчужной повязке, и коса под ней оставалась открытой как знак невесты.","href":"/muzei/narodnyy-kostyum/den/03-31/"},"04-01":{"t":"Тула — мастеровые-оружейники","d":"Тульский оружейник снимал кожаный фартук только в праздник, и под ним всегда оказывался добротный суконный кафтан мастера.","href":"/muzei/narodnyy-kostyum/den/04-01/"},"04-02":{"t":"Харьковская губ. — Слобожанщина","d":"Слобожанская плахта из двух клетчатых полотнищ дожила до музейной витрины, сохранив узор, который ткали ещё прабабки.","href":"/muzei/narodnyy-kostyum/den/04-02/"},"04-03":{"t":"Муромский уезд — праздничный наряд","d":"Муромская молодуха надевала кокошник с жемчужной поднизью раз в год, и этот кокошник пережил и её, и весь уезд.","href":"/muzei/narodnyy-kostyum/den/04-03/"},"04-04":{"t":"Суджа — южное пограничье","d":"На суджанском пограничье русская понёва и малороссийская плахта сошлись в одной деревне и обе дожили до наших дней.","href":"/muzei/narodnyy-kostyum/den/04-04/"},"04-05":{"t":"Забайкалье, семейские — свадьба","d":"Семейские невесты Забайкалья надевали по нескольку ниток янтаря, и этот свадебный наряд семейских сохранился до сих пор.","href":"/muzei/narodnyy-kostyum/den/04-05/"},"04-06":{"t":"Рязанская обл., колхоз — 1930-е","d":"В рязанском колхозе 1930-х ситцевое платье вытеснило понёву, но бабушки упрямо донашивали свою клетчатую понёву до конца.","href":"/muzei/narodnyy-kostyum/den/04-06/"},"04-07":{"t":"Касимов — Благовещение, весенний девичий наряд","d":"На Благовещение касимовские девушки впервые после зимы выходили в лёгком сарафане, и весенняя повязка дожила до музея.","href":"/muzei/narodnyy-kostyum/den/04-07/"},"04-08":{"t":"Талашкино — мастерские Тенишевой","d":"Княгиня Тенишева собрала в Талашкине крестьянскую одежду, когда её выбрасывали, и это собрание спасло сотни вещей.","href":"/muzei/narodnyy-kostyum/den/04-08/"},"04-09":{"t":"Вытегра — будничная одежда льняного края","d":"Вытегорская будничная одежда шилась из домашнего льна, и простой синий крашенник пережил все праздничные наряды края.","href":"/muzei/narodnyy-kostyum/den/04-09/"},"04-10":{"t":"Великое Село — ярославское полотно","d":"Полотно из Великого Села славилось тонкостью на всю Россию, и ткацкое ремесло села дожило до наших дней.","href":"/muzei/narodnyy-kostyum/den/04-10/"},"04-11":{"t":"Кубань, казачки — праздничная кофта и юбка","d":"Кубанская казачка шила праздничную парочку — кофту и юбку из одной ткани, и этот наряд пережил все запреты казачества.","href":"/muzei/narodnyy-kostyum/den/04-11/"},"04-12":{"t":"Киевская Русь — княжеская семья в «Изборнике Святослава» 1073 г.","d":"Миниатюра «Изборника Святослава» 1073 года сохранила, как одевалась княжеская семья, — корзно князя видно и спустя девять веков.","href":"/muzei/narodnyy-kostyum/den/04-12/"},"04-13":{"t":"Петербург, фрейлины — придворный кокошник","d":"Николай I вернул ко двору русский кокошник, и фрейлины носили его на каждом большом выходе до самого 1917 года.","href":"/muzei/narodnyy-kostyum/den/04-13/"},"04-14":{"t":"Фатеж — рубаха как бельё и как наряд","d":"Фатежская рубаха служила и бельём, и нарядом, и по одной вышивке на рукаве село читало, чья она и по какому поводу.","href":"/muzei/narodnyy-kostyum/den/04-14/"},"04-15":{"t":"Старица — старик-большак","d":"Старицкий большак ходил в самом длинном кафтане семьи, и по этому кафтану вся деревня узнавала главу дома.","href":"/muzei/narodnyy-kostyum/den/04-15/"},"04-16":{"t":"Торжок — торжокские горожанки","d":"Торжокские горожанки носили золотное шитьё своих мастериц, и это шитьё дожило до наших дней как ремесло города.","href":"/muzei/narodnyy-kostyum/den/04-16/"},"04-17":{"t":"Олонецкая губ. — девичья повязка «на выданье»","d":"Олонецкая девушка надевала шитую повязку на выданье, и открытая коса под ней говорила селу о ней без слов.","href":"/muzei/narodnyy-kostyum/den/04-17/"},"04-18":{"t":"Москва, трактир — половые и приказчики","d":"Московский половой работал в белой рубахе навыпуск, и эту рубаху по всей Москве узнавали с порога трактира.","href":"/muzei/narodnyy-kostyum/den/04-18/"},"04-19":{"t":"Подольская губ. — вышитые сорочки Подолии","d":"Подольская сорочка с плотной вышивкой по рукаву пережила своих мастериц и сохранила узор их села до наших дней.","href":"/muzei/narodnyy-kostyum/den/04-19/"},"04-20":{"t":"Мурман — поморы-зимовщики","d":"Поморы уходили на Мурман на тресковый промысел в бахилах и роканах, и эта одежда держала их живыми в ледяной воде.","href":"/muzei/narodnyy-kostyum/den/04-20/"},"04-21":{"t":"Старый Оскол — понёва и вышитые рубахи","d":"Старооскольская понёва в красную клетку пережила село, и по её узору и сегодня видно, откуда была хозяйка.","href":"/muzei/narodnyy-kostyum/den/04-21/"},"04-22":{"t":"Невьянск — свадьба уральских заводских","d":"Невьянская заводская невеста выходила в шёлковом сарафане из лавки, и этот заводской наряд хранит уральский музей.","href":"/muzei/narodnyy-kostyum/den/04-22/"},"04-23":{"t":"Мышкин — валяльщики","d":"Мышкинские валяльщики катали валенки на всю губернию, и ремесло городка устояло и вернулось в его музеи.","href":"/muzei/narodnyy-kostyum/den/04-23/"},"04-24":{"t":"Терек — черкеска, бешмет, бурка","d":"Терские казаки взяли у горцев черкеску с газырями, и она стала их собственным мундиром на два столетия.","href":"/muzei/narodnyy-kostyum/den/04-24/"},"04-25":{"t":"Псковская губ., Вербное — дети с вербами","d":"В Вербное псковские дети выходили с вербами в новых рубахах, и этот весенний обычай дожил до нашего воскресенья.","href":"/muzei/narodnyy-kostyum/den/04-25/"},"04-26":{"t":"Осташков — рыбаки Селигера","d":"Осташковские рыбаки ходили по Селигеру в кожанах, и рыбный промысел города пережил все смены власти.","href":"/muzei/narodnyy-kostyum/den/04-26/"},"04-27":{"t":"Ленинград, 1920-е — комсомольская свадьба","d":"Ленинградская комсомолка 1920-х выходила замуж в простом платье и красной косынке, и снимки этих свадеб сохранились.","href":"/muzei/narodnyy-kostyum/den/04-27/"},"04-28":{"t":"Мезень, 1920-е — экспедиции РЭМ","d":"Экспедиции РЭМ 1920-х вывезли с Мезени целые сундуки одежды, и этот гардероб северной реки уцелел в фондах.","href":"/muzei/narodnyy-kostyum/den/04-28/"},"04-29":{"t":"Переселенцы на Томскую губ. — дорога за Урал","d":"Переселенцы везли за Урал свои понёвы и армяки, и в томской деревне родной наряд прожил ещё целый век.","href":"/muzei/narodnyy-kostyum/den/04-29/"},"04-30":{"t":"Щигры — пахарь в поле","d":"Щигровский пахарь выходил в поле в холщовой рубахе и лаптях, и эта рабочая одежда сохранилась в курском музее.","href":"/muzei/narodnyy-kostyum/den/04-30/"},"05-01":{"t":"Пудож — мужская охотничья и праздничная одежда","d":"Пудожский охотник уходил в лес на неделю в сермяге с лузаном за плечами, а домой к празднику переодевался в вышитую косоворотку.","href":"/muzei/narodnyy-kostyum/den/05-01/"},"05-02":{"t":"Тульская губ., Пасха — праздничный выход в церковь","d":"К пасхальной заутрене тульская девушка впервые надевала рубаху, которую шила всю зиму, и в ней же наутро шла христосоваться.","href":"/muzei/narodnyy-kostyum/den/05-02/"},"05-03":{"t":"Кашин — праздничный наряд Кашинского уезда","d":"Кашинский кокошник шили всей семьёй годами, и после свадьбы его прятали в сундук до праздника, когда молодуха выходила к обедне.","href":"/muzei/narodnyy-kostyum/den/05-03/"},"05-04":{"t":"Белгород — праздничный наряд Белгородского уезда","d":"Белгородская понёва с красной клеткой выдавала замужнюю издалека, и девушка не смела надеть её даже на праздник до самого венца.","href":"/muzei/narodnyy-kostyum/den/05-04/"},"05-05":{"t":"Кимры — сапожники","d":"Кимрские сапожники шили обувь на всю Россию и везли её возами на ярмарки, а сами дома часто ходили в старых лаптях.","href":"/muzei/narodnyy-kostyum/den/05-05/"},"05-06":{"t":"Новгородская губ., Егорий — Егорий вешний, первый выгон скота","d":"На Егория новгородская хозяйка выгоняла корову в поле вербой, сохранённой с Вербного воскресенья, а пастух в армяке трубил в берестяной рожок.","href":"/muzei/narodnyy-kostyum/den/05-06/"},"05-07":{"t":"Гребенские станицы — старообрядцы на Тереке","d":"Гребенские казаки взяли у соседей-горцев черкеску и бешмет, но старую веру и русскую молитву пронесли через три века на Тереке.","href":"/muzei/narodnyy-kostyum/den/05-07/"},"05-08":{"t":"Тульская губ. — молодуха, первый год замужества","d":"Первый год после свадьбы тульская молодуха носила самую нарядную кичку в деревне, а после рождения ребёнка убор становился скромнее.","href":"/muzei/narodnyy-kostyum/den/05-08/"},"05-09":{"t":"Владимирская губ., Красная горка — смотрины и гулянья молодых","d":"На Красную горку владимирские девушки выходили на гулянье в лучшем сарафане, и сваты высматривали невест прямо на пригорке у села.","href":"/muzei/narodnyy-kostyum/den/05-09/"},"05-10":{"t":"Петербург, улица — разносчики и торговки","d":"Охтенская молочница каждое утро несла петербургским господам кувшины с молоком, и её узнавали по повязке задолго до крика «молоко».","href":"/muzei/narodnyy-kostyum/den/05-10/"},"05-11":{"t":"Волынская губ. — праздничный наряд Волыни","d":"Волынская невеста вышивала себе сорочку белым по белому, и праздничный узор на рукаве видели только те, кто стоял совсем рядом.","href":"/muzei/narodnyy-kostyum/den/05-11/"},"05-12":{"t":"Мологский уезд — детская игровая одежда","d":"Мологские дети до семи лет бегали в одной длинной рубашке, а штаны или сарафан получали, только когда начинали помогать в поле.","href":"/muzei/narodnyy-kostyum/den/05-12/"},"05-13":{"t":"Владимиро-Суздальская земля — погребальный шёлк и тесьма XII–XIII вв.","d":"Обрывок золотной тесьмы из суздальского погребения пролежал в земле восемьсот лет и рассказал о наряде княгини больше любой летописи.","href":"/muzei/narodnyy-kostyum/den/05-13/"},"05-14":{"t":"Москва, коронация 1724 — коронационное платье Екатерины I","d":"Платье для коронации Екатерины I в 1724 году шили в Москве в спешке, и серебряное шитьё на нём было таким тяжёлым, что ходить в нём было трудно.","href":"/muzei/narodnyy-kostyum/den/05-14/"},"05-15":{"t":"Ярославская губ., отход — отходник-печник в дороге","d":"Ярославский печник уходил на заработки по весне в армяке и лаптях, а на зиму возвращался домой в сапогах и с гостинцами для всей семьи.","href":"/muzei/narodnyy-kostyum/den/05-15/"},"05-16":{"t":"Смоленская обл., 1946 — послевоенная деревня, перешитое из шинелей","d":"После войны смоленские вдовы перешивали солдатские шинели в пальто детям, и в одном сукне носили его по очереди все младшие.","href":"/muzei/narodnyy-kostyum/den/05-16/"},"05-17":{"t":"Кижи — заонежский костюм в музее","d":"Заонежские сарафаны, собранные по деревням вокруг Кижей, попали в музей, когда хозяйки уже не надеялись, что их кто-то наденет снова.","href":"/muzei/narodnyy-kostyum/den/05-17/"},"05-18":{"t":"Холмогоры — праздничный наряд горожанок и крестьянок","d":"Холмогорские горожанки шили сарафаны из привозного штофа, и праздничный наряд северной деревни мог поспорить с московским.","href":"/muzei/narodnyy-kostyum/den/05-18/"},"05-19":{"t":"Богородский уезд — фабричные и крестьянский наряд","d":"Богородская ткачиха первой в деревне сменила сарафан на ситцевую кофту с юбкой, и мать долго не пускала её в таком виде в церковь.","href":"/muzei/narodnyy-kostyum/den/05-19/"},"05-20":{"t":"Нижний Новгород — картуз и поддёвка, мужик на ярмарке","d":"На Нижегородской ярмарке крестьянин покупал первый в жизни картуз и поддёвку, и с тех пор в деревне его звали по-купечески.","href":"/muzei/narodnyy-kostyum/den/05-20/"},"05-21":{"t":"Новгородская губ., жемчуг — жемчужное низание","d":"Новгородский кокошник низали речным жемчугом, который девушки сами собирали в северных реках, и такой убор переходил к внучке.","href":"/muzei/narodnyy-kostyum/den/05-21/"},"05-22":{"t":"Оренбургская губ. — оренбургские казаки","d":"Оренбургская казачка вязала пуховый платок такой тонкий, что его продевали сквозь обручальное кольцо, и этот платок ценился в столицах.","href":"/muzei/narodnyy-kostyum/den/05-22/"},"05-23":{"t":"Рыльск — южный комплекс с запоной","d":"Рыльская запона, надетая поверх рубахи и понёвы, закрывала женщину от плеч до колен и делала праздничный наряд одним цельным полотном.","href":"/muzei/narodnyy-kostyum/den/05-23/"},"05-24":{"t":"Костромская губ. — вдовий наряд","d":"Костромская вдова убирала в сундук красный сарафан на всю оставшуюся жизнь и выходила на люди только в тёмном и без вышивки.","href":"/muzei/narodnyy-kostyum/den/05-24/"},"05-25":{"t":"Шенкурск — штофные сарафаны и душегреи","d":"Шенкурская невеста получала в приданое штофный сарафан, который берегли так, что его надевали только на свадьбу и на Троицу.","href":"/muzei/narodnyy-kostyum/den/05-25/"},"05-26":{"t":"Москва, коронация 1896 — коронация Николая II (14 мая ст. ст.)","d":"На коронацию 1896 года фрейлины надели платья с кокошниками в русском стиле, а через четыре дня гулянье на Ходынке обернулось давкой.","href":"/muzei/narodnyy-kostyum/den/05-26/"},"05-27":{"t":"Егорьевск — семья сельского священника","d":"Дочь егорьевского священника носила не крестьянский сарафан и не городское платье, а что-то среднее, и по одежде её узнавали в любом селе.","href":"/muzei/narodnyy-kostyum/den/05-27/"},"05-28":{"t":"Херсонская губ. — праздничный наряд степного юга","d":"Херсонский чумак уходил в степь за солью в смазанной дёгтем рубахе, чтобы отпугнуть мошкару, а праздничную берёг для возвращения домой.","href":"/muzei/narodnyy-kostyum/den/05-28/"},"05-29":{"t":"Рязанская губ., пахота — весенняя пахота","d":"Рязанский пахарь выходил в поле на рассвете в старой посконной рубахе, а новую надевал только после того, как вся земля была вспахана.","href":"/muzei/narodnyy-kostyum/den/05-29/"},"05-30":{"t":"Гуслицы — старообрядческая вышивка и одежда","d":"Гуслицкие старообрядцы вышивали крестом так плотно, что узор на полотенце держался дольше самой ткани и узнавался по всей Московской губернии.","href":"/muzei/narodnyy-kostyum/den/05-30/"},"05-31":{"t":"Вологодская обл., 1950-е — деревня 1950-х","d":"В вологодской деревне пятидесятых бабушка ещё донашивала сарафан, а внучка уже бегала на танцы в ситцевом платье, купленном в райцентре.","href":"/muzei/narodnyy-kostyum/den/05-31/"},"06-01":{"t":"Великий Устюг — музей-заповедник: северная коллекция","d":"Устюжский музей собирал крестьянские сарафаны по деревням Северной Двины, и многие вещи попали в фонд прямо из бабушкиных сундуков.","href":"/muzei/narodnyy-kostyum/den/06-01/"},"06-02":{"t":"Тверская губ. — мальчик в первых портах","d":"До пяти-шести лет тверской мальчишка бегал в одной длинной рубахе, и первые порты, сшитые матерью, означали, что он уже помощник отцу.","href":"/muzei/narodnyy-kostyum/den/06-02/"},"06-03":{"t":"Рязанская губ. — тканые пояса","d":"Рязанская невеста ткала пояса к свадьбе десятками, чтобы одарить всю родню жениха, и по узору пояса узнавали её руку.","href":"/muzei/narodnyy-kostyum/den/06-03/"},"06-04":{"t":"Оренбургское войско — оренбургские казаки","d":"Оренбургская казачка вязала пуховый платок такой тонкий, что его продевали сквозь обручальное кольцо, и такой платок казак брал из дома в поход.","href":"/muzei/narodnyy-kostyum/den/06-04/"},"06-05":{"t":"Острогожск — «чёрная» вышивка и понёва","d":"Воронежские мастерицы вышивали рубахи чёрной шерстью так густо, что узор на рукавах издали казался сплошным тёмным полотном.","href":"/muzei/narodnyy-kostyum/den/06-05/"},"06-06":{"t":"Архангельская губ. — смертная одежда и поминальный наряд","d":"Северная крестьянка шила себе смертную рубаху загодя, ещё в силе, и держала её на дне сундука под праздничными нарядами.","href":"/muzei/narodnyy-kostyum/den/06-06/"},"06-07":{"t":"Устья (Устьянский р-н) — северный праздничный комплекс, эталон РЭМ 13066-68","d":"Устьянский праздничный комплекс попал в Этнографический музей целиком, от кокошника до пояса, и стал эталоном северного наряда.","href":"/muzei/narodnyy-kostyum/den/06-07/"},"06-08":{"t":"Старая Рязань — старорязанские клады: украшения княжеского убора","d":"Старорязанские клады зарыли перед батыевым разгромом 1237 года, и золотые колты княжеского убора пролежали в земле больше шести веков.","href":"/muzei/narodnyy-kostyum/den/06-08/"},"06-09":{"t":"Москва, 1613 — венчание на царство Михаила Фёдоровича","d":"Шестнадцатилетний Михаил Романов венчался на царство в шапке Мономаха и бармах, а бояре стояли вокруг в высоких горлатных шапках.","href":"/muzei/narodnyy-kostyum/den/06-09/"},"06-10":{"t":"Юрьев-Польский — пастух: рожок и армяк","d":"Владимирские пастухи-рожечники играли так слаженно, что хор Кондратьева в конце XIX века возили выступать в Москву и Петербург.","href":"/muzei/narodnyy-kostyum/den/06-10/"},"06-11":{"t":"Поречье (Смоленская губ.) — наряд западного пограничья","d":"В смоленском Поречье женщины носили андарак вместо понёвы, и по одной этой юбке было видно, что белорусские деревни совсем рядом.","href":"/muzei/narodnyy-kostyum/den/06-11/"},"06-12":{"t":"Луховицы — огуречники Коломенского уезда","d":"Луховицкие огородники возили огурцы возами на московские рынки, и на выручку с грядок хозяйки покупали себе праздничные ситцы.","href":"/muzei/narodnyy-kostyum/den/06-12/"},"06-13":{"t":"Ярославская губ., синильщики — марена и крашенина","d":"Ярославский синильщик ходил с руками, окрашенными по локоть, и по этим синим рукам его узнавали в любой деревне.","href":"/muzei/narodnyy-kostyum/den/06-13/"},"06-14":{"t":"Сибирское войско — сибирские казаки","d":"Сибирские казаки несли службу на Иртышской линии, и зимний караул в степи стоял в собачьих дохах поверх форменного мундира.","href":"/muzei/narodnyy-kostyum/den/06-14/"},"06-15":{"t":"Иркутск — сибирское купечество","d":"Иркутская купчиха носила китайский шёлк, привезённый через Кяхту, и её платье стоило дороже иного дома в слободе.","href":"/muzei/narodnyy-kostyum/den/06-15/"},"06-16":{"t":"Екатеринославская губ. — потомки запорожцев","d":"После роспуска Сечи в 1775 году запорожцы осели по Екатеринославщине, и их внуки долго хранили дедовские жупаны в сундуках.","href":"/muzei/narodnyy-kostyum/den/06-16/"},"06-17":{"t":"Воронежская губ., Семик — девичьи гулянья и кумление","d":"На Семик воронежские девушки завивали берёзку и кумились через венок, а после этого называли друг друга кумами до следующей весны.","href":"/muzei/narodnyy-kostyum/den/06-17/"},"06-18":{"t":"Тарнога — праздничный наряд Тарногского края","d":"Тарногская крестьянка надевала штофный сарафан только на престольный праздник, и в сундуке он переходил от бабушки к внучке почти неношеным.","href":"/muzei/narodnyy-kostyum/den/06-18/"},"06-19":{"t":"Орехово-Зуево, 1920-е — фабричная молодёжь","d":"При Морозовской фабрике в Орехово-Зуеве футбол завели ещё до революции, и в 1920-е спортивная форма стала новой модой рабочей слободы.","href":"/muzei/narodnyy-kostyum/den/06-19/"},"06-20":{"t":"Пинега, Троица — девичьи гулянья и венки","d":"На Троицу пинежские девушки пускали венки по воде, а потом шли в хоровод в лучших сарафанах, которые берегли к этому дню весь год.","href":"/muzei/narodnyy-kostyum/den/06-20/"},"06-21":{"t":"Рязань, сегодня — мастерицы реконструируют понёву","d":"Рязанские мастерицы сегодня ткут понёвы на старых станах по музейным образцам, сверяя каждую клетку с выцветшим подлинником.","href":"/muzei/narodnyy-kostyum/den/06-21/"},"06-22":{"t":"Торопец — торопецкие кокошники и жемчуг","d":"Торопецкие купчихи носили кокошники, сплошь унизанные речным жемчугом, и такой кокошник ценился дороже лавки с товаром.","href":"/muzei/narodnyy-kostyum/den/06-22/"},"06-23":{"t":"Павловск (Воронежская губ.) — однодворцы: сарафан среди понёвного края","d":"Воронежские однодворцы, потомки служилых людей, носили сарафан среди понёвных деревень и этим отличали себя от соседей-крестьян.","href":"/muzei/narodnyy-kostyum/den/06-23/"},"06-24":{"t":"Ярославская губ. — родины: одежда роженицы","d":"Ярославская роженица рожала в бане в старой будничной рубахе, а младенца принимали в отцовскую рубаху, чтобы отец его любил.","href":"/muzei/narodnyy-kostyum/den/06-24/"},"06-25":{"t":"Перемышль — девичьи хороводы в Петровки","d":"В Петровки перемышльские девушки водили хороводы над Окой и меняли наряды по нескольку раз за вечер, показывая приданое.","href":"/muzei/narodnyy-kostyum/den/06-25/"},"06-26":{"t":"Кама — сплавщики Пермской губ.","d":"Пермские сплавщики гнали по Чусовой барки с уральским железом, и весной на сплав нанимали тысячи мужиков в армяках и бахилах.","href":"/muzei/narodnyy-kostyum/den/06-26/"},"06-27":{"t":"Уфимская губ. — пасечники-русские","d":"Русский пасечник Уфимской губернии работал у ульев в белой льняной рубахе, потому что пчела злее кидается на тёмное.","href":"/muzei/narodnyy-kostyum/den/06-27/"},"06-28":{"t":"Богородское (Нижегородская губ.) — кожевники: юфть и сапоги","d":"Кожевники нижегородского Богородского выделывали юфть на всю Волгу, и сапоги из неё носили от бурлака до ярмарочного купца.","href":"/muzei/narodnyy-kostyum/den/06-28/"},"06-29":{"t":"Забайкальское войско — забайкальские казаки","d":"Забайкальские казаки носили жёлтые лампасы, а на зимней службе у китайской границы обувались в меховые унты, переняв их у бурят.","href":"/muzei/narodnyy-kostyum/den/06-29/"},"06-30":{"t":"Чухлома — девичий наряд на летних гуляньях","d":"Мужья и женихи-питерщики везли в Чухлому из столицы шёлк и ленты, и на летних гуляньях чухломские девушки щеголяли нарядами богаче соседских.","href":"/muzei/narodnyy-kostyum/den/06-30/"},"07-01":{"t":"Великие Луки — праздничный наряд Великолукского уезда","d":"Великолукская молодуха ткала браный передник всю зиму, а надевала его только на престольный праздник у своей церкви.","href":"/muzei/narodnyy-kostyum/den/07-01/"},"07-02":{"t":"Курск, Коренная — Коренная ярмарка: праздничный выход","d":"На Коренную ярмарку под Курском съезжалась вся губерния, и крестьянки везли туда в сундуке самую нарядную понёву.","href":"/muzei/narodnyy-kostyum/den/07-02/"},"07-03":{"t":"Москва, Кремль — царицына мастерская палата: одежда цариц и царевен","d":"В Царицыной мастерской палате золотошвеи годами расшивали один летник, а царевна надевала его лишь на большой выход.","href":"/muzei/narodnyy-kostyum/den/07-03/"},"07-04":{"t":"Бобров — праздничный наряд Бобровского уезда","d":"Бобровская молодуха носила рогатую кичку с первого дня замужества, и рога на ней означали, что она уже хозяйка в доме.","href":"/muzei/narodnyy-kostyum/den/07-04/"},"07-05":{"t":"Смоленская губ. — свадьба","d":"Смоленская невеста дарила расшитые рушники всей родне жениха, и по их числу свекровь судила, какая работница пришла в дом.","href":"/muzei/narodnyy-kostyum/den/07-05/"},"07-06":{"t":"Кяхта — чаеторговцы","d":"Кяхтинские купчихи шили платья из китайского шёлка, который шёл через их город вместе с чаем на всю Россию.","href":"/muzei/narodnyy-kostyum/den/07-06/"},"07-07":{"t":"Полесье, Купалье — венки и белые рубахи","d":"В купальскую ночь полесские девушки пускали свои травяные венки по реке, а утром по ним гадали, кому выходить замуж.","href":"/muzei/narodnyy-kostyum/den/07-07/"},"07-08":{"t":"Измайлово — царская охота: охотничий костюм","d":"Сокольники царя Алексея Михайловича выезжали в Измайлово в красных кафтанах с золотыми нашивками, видных издалека.","href":"/muzei/narodnyy-kostyum/den/07-08/"},"07-09":{"t":"Москва, хор Пятницкого — сценический костюм и подлинник","d":"Митрофан Пятницкий выводил на сцену воронежских крестьян в их собственных нарядах, а не в костюмах из театральной мастерской.","href":"/muzei/narodnyy-kostyum/den/07-09/"},"07-10":{"t":"Шексна, 1909 — Прокудин-Горский: цветные снимки нарядов","d":"В 1909 году Прокудин-Горский снял крестьянок на Шексне в цвете, и мы впервые увидели, какого цвета был их кумач.","href":"/muzei/narodnyy-kostyum/den/07-10/"},"07-11":{"t":"Могилёвская губ. — белорусский праздничный наряд","d":"Могилёвская молодица ткала полосатый андарак сама, и по его цвету соседки узнавали, из какой она деревни.","href":"/muzei/narodnyy-kostyum/den/07-11/"},"07-12":{"t":"Усть-Цильма — «Горка» на Петров день","d":"На усть-цилемскую «Горку» в Петров день девушки выходили в парчовых сарафанах, которые хранили в сундуках десятилетиями.","href":"/muzei/narodnyy-kostyum/den/07-12/"},"07-13":{"t":"Городец — праздничный наряд Заволжья","d":"Городецкая молодуха шла на ярмарку в сарафане из синей набойки, узор которой резали на досках местные мастера.","href":"/muzei/narodnyy-kostyum/den/07-13/"},"07-14":{"t":"Тотьма — праздничный наряд солеваров и крестьян","d":"Тотемский солевар неделями стоял у варниц в холщовой рубахе, а в праздник надевал суконный зипун не хуже купеческого.","href":"/muzei/narodnyy-kostyum/den/07-14/"},"07-15":{"t":"Сарапул — скорняки: шубы и меха","d":"Сарапульские скорняки шили шубы для всего Прикамья, и лисья шуба купчихи передавалась в семье от матери к дочери.","href":"/muzei/narodnyy-kostyum/den/07-15/"},"07-16":{"t":"Амур — амурские казаки","d":"Амурские казаки получили жёлтые лампасы, и по этому цвету их узнавали на всём Дальнем Востоке от Благовещенска до Хабаровска.","href":"/muzei/narodnyy-kostyum/den/07-16/"},"07-17":{"t":"Троице-Сергиева лавра — богомольцы в пути","d":"Богомольцы шли к Троице-Сергиевой лавре пешком сотни вёрст, неся лапти за плечом и надевая их только у монастырских стен.","href":"/muzei/narodnyy-kostyum/den/07-17/"},"07-18":{"t":"Самарская губ. — бурлацкая артель на Волге","d":"Бурлак за путину стирал о лямку несколько посконных рубах, и под Самарой артели покупали новые прямо на пристанях.","href":"/muzei/narodnyy-kostyum/den/07-18/"},"07-19":{"t":"Боровичи — дети-пастушки","d":"Боровичский пастушок выгонял стадо до рассвета в одной холщовой рубахе и греться бежал к костру из сосновых шишек.","href":"/muzei/narodnyy-kostyum/den/07-19/"},"07-20":{"t":"Задонск — богомольцы у Задонского монастыря","d":"К мощам Тихона Задонского после 1861 года шли тысячи богомольцев, и паломницы надевали тёмные понёвы вместо праздничных.","href":"/muzei/narodnyy-kostyum/den/07-20/"},"07-21":{"t":"Кашинский уезд Тверской губ. — свадьба","d":"Кашинская невеста на свадьбе меняла девичью повязку на кокошник, и с этой минуты косу ей больше никто не видел.","href":"/muzei/narodnyy-kostyum/den/07-21/"},"07-22":{"t":"Керженец — старообрядцы Заволжья","d":"Керженские староверки шили сарафаны по старому крою и молились в них на лестовках, хотя за раскол их не раз сгоняли с места.","href":"/muzei/narodnyy-kostyum/den/07-22/"},"07-23":{"t":"Соловки — одежда богомольцев на пути в монастырь","d":"Богомольцы плыли на Соловки на монастырском пароходе, а трудники оставались там на год работать в одних подрясниках.","href":"/muzei/narodnyy-kostyum/den/07-23/"},"07-24":{"t":"Льгов, 1930 — раскулачивание: что взяли с собой","d":"Курская семья из-под Льгова, высланная в 1930 году, успела взять с собой только праздничную понёву, и она дожила до наших дней.","href":"/muzei/narodnyy-kostyum/den/07-24/"},"07-25":{"t":"Тарбагатай — возрождение семейской одежды","d":"Семейский хор из Тарбагатая вынес наряды бабушек на сцену, и снова шить кички с лентами стали уже молодые женщины.","href":"/muzei/narodnyy-kostyum/den/07-25/"},"07-26":{"t":"Касли — литейщики Каслинского завода","d":"Каслинский формовщик работал у вагранки в кожаном фартуке, а его чугунный павильон увезли в Париж на Всемирную выставку 1900 года.","href":"/muzei/narodnyy-kostyum/den/07-26/"},"07-27":{"t":"Таврическая губ. — дорожная одежда чумаков на соляных озёрах","d":"Чумак мазал свою сорочку дёгтем, чтобы её не ела вошь в дороге, и за долгий путь к крымским соляным озёрам она становилась чёрной.","href":"/muzei/narodnyy-kostyum/den/07-27/"},"07-28":{"t":"Мстёра — вышивка «белым по белому»","d":"Мстёрские вышивальщицы клали гладь белым по белому так тонко, что узор на рубахе проступал только на свету.","href":"/muzei/narodnyy-kostyum/den/07-28/"},"07-29":{"t":"Уссури — уссурийские казаки","d":"Уссурийские казаки заселяли берег Уссури семьями, и казачки шили там одежду из того, что привезли с собой с Дона.","href":"/muzei/narodnyy-kostyum/den/07-29/"},"07-30":{"t":"Курская губ. — покос: косцы и гребельщицы","d":"На покос курские молодухи выходили в лучших рубахах, потому что на лугу их видела вся деревня и женихи из соседних сёл.","href":"/muzei/narodnyy-kostyum/den/07-30/"},"07-31":{"t":"Арзамас — праздничный наряд Арзамасского уезда","d":"Арзамасская молодуха вышивала кокошник позументом, и на Масленичных гуляньях по нему видели, сколько у её мужа денег.","href":"/muzei/narodnyy-kostyum/den/07-31/"},"08-01":{"t":"Павлово — кузнецы: рабочая одежда","d":"Павловские кустари ковали замки и ножи прямо в избах, и кожаный запон кузнеца переходил от отца к сыну вместе с наковальней.","href":"/muzei/narodnyy-kostyum/den/08-01/"},"08-02":{"t":"Орловская губ., Болховский уезд — Ильин день: жница в праздничной рубахе","d":"На Ильин день болховские жницы доставали из сундука праздничные рубахи с красными плечами, хотя рожь в поле ещё стояла недожатой.","href":"/muzei/narodnyy-kostyum/den/08-02/"},"08-03":{"t":"Москва, стрелецкие слободы — стрелецкие кафтаны по полкам","d":"Московских стрельцов узнавали по цвету кафтана, и каждый полк от воротника до шапки носил свой цвет, будто живое знамя.","href":"/muzei/narodnyy-kostyum/den/08-03/"},"08-04":{"t":"Петербург, царская детская — придворные кормилицы в «русском» наряде","d":"Кормилиц для царских детей одевали в парчовые сарафаны и кокошники, и этот «русский» наряд при дворе носили до самого 1917 года.","href":"/muzei/narodnyy-kostyum/den/08-04/"},"08-05":{"t":"Вельск — праздничные кокошники и сарафаны","d":"Вельская невеста шила к свадьбе штофный сарафан, а кокошник с жемчужной поднизью доставался ей от матери и бабушки.","href":"/muzei/narodnyy-kostyum/den/08-05/"},"08-06":{"t":"Моршанск — праздничный наряд Моршанского уезда","d":"Моршанские хлеботорговцы богатели на пристани у Цны, а их жёны выходили на праздник в понёвах с таким шитьём, что приценивались заезжие купцы.","href":"/muzei/narodnyy-kostyum/den/08-06/"},"08-07":{"t":"Елабуга, купечество — купеческая свадьба","d":"В купеческой Елабуге свадьбу гуляли по три дня, и невеста успевала за это время сменить несколько шёлковых платьев из приданого.","href":"/muzei/narodnyy-kostyum/den/08-07/"},"08-08":{"t":"Тульская губ., Епифанский уезд — закладное ткачество понёв","d":"Епифанская ткачиха закладывала узор понёвы цветной нитью прямо на стане, и по клетке соседи узнавали, из какого она села.","href":"/muzei/narodnyy-kostyum/den/08-08/"},"08-09":{"t":"Семиречье — семиреченские казаки","d":"Семиреченские казаки поставили станицы у самых гор Алатау, и казачки шили там праздничные кофты из шёлка, привезённого караванами из Кульджи.","href":"/muzei/narodnyy-kostyum/den/08-09/"},"08-10":{"t":"Яренск, младенцы — младенец в люльке: свивальник и пелёнки","d":"Яренского младенца пеленали в старую отцовскую рубаху, и туго затянутый свивальник служил ему единственной одеждой до первых шагов.","href":"/muzei/narodnyy-kostyum/den/08-10/"},"08-11":{"t":"Москва, 1948 — школьная форма","d":"В 1948 году московские школьницы надели коричневые платья с фартуками, и белый воротничок к ним пришивали заново каждое воскресенье.","href":"/muzei/narodnyy-kostyum/den/08-11/"},"08-12":{"t":"Архангельск, Северный хор — подлинные наряды на сцене с 1926 г.","d":"Северный хор Антонины Колотиловой с 1926 года выходил на сцену в подлинных бабушкиных сарафанах, собранных по деревням Архангельского края.","href":"/muzei/narodnyy-kostyum/den/08-12/"},"08-13":{"t":"Слободской (Вятская губ.) — праздничный наряд","d":"Слободские купцы возили пушнину до самого Архангельска, а крестьянки уезда шили праздничные сарафаны из привозной синей набойки.","href":"/muzei/narodnyy-kostyum/den/08-13/"},"08-14":{"t":"Нёнокса, Летний берег — стирка на море: что носили и как берегли","d":"Поморки Нёноксы полоскали бельё в студёной морской воде и колотили его вальком, а праздничную рубаху так стирали лишь пару раз в год.","href":"/muzei/narodnyy-kostyum/den/08-14/"},"08-15":{"t":"Макарьев — купцы Макарьевской ярмарки","d":"До пожара 1816 года главная ярмарка России шумела под стенами Макарьевского монастыря, и купцы со всей страны съезжались туда в лучших кафтанах.","href":"/muzei/narodnyy-kostyum/den/08-15/"},"08-16":{"t":"Минская губ. — белорусский праздничный наряд: андарак и намитка","d":"Минская молодуха после венца навсегда покрывала голову намиткой, длинным белым полотенцем, которое обматывала вокруг лица и шеи.","href":"/muzei/narodnyy-kostyum/den/08-16/"},"08-17":{"t":"Кадников — праздничный наряд Кадниковского уезда","d":"Кадниковские девушки готовили к празднику кумачовые сарафаны и вышитые полотенца, которыми потом украшали дуги свадебного поезда.","href":"/muzei/narodnyy-kostyum/den/08-17/"},"08-18":{"t":"Шацк — праздничный женский убор","d":"Шацкая молодуха надевала рогатую кичку с первого дня замужества, и по богатству её убора на селе судили о достатке мужнего дома.","href":"/muzei/narodnyy-kostyum/den/08-18/"},"08-19":{"t":"Варнавин — свадьба лесного Заволжья","d":"Варнавинская невеста ехала к венцу через ветлужские леса, а дружка вёз следом на телеге её сундук с приданым и вышитыми рушниками.","href":"/muzei/narodnyy-kostyum/den/08-19/"},"08-20":{"t":"Рогожская слобода — моленный кафтан старообрядцев","d":"На Рогожском кладбище старообрядцы стояли на молитве в длинных тёмных кафтанах, сшитых по допетровскому образцу, без единой пуговицы на виду.","href":"/muzei/narodnyy-kostyum/den/08-20/"},"08-21":{"t":"Красное-на-Волге — серебряники: серьги и перстни","d":"Красносельские серебряники сдавали скупщикам серьги и перстни мешками, и эти украшения надевали невесты от Костромы до Нижегородского торга.","href":"/muzei/narodnyy-kostyum/den/08-21/"},"08-22":{"t":"Астраханское войско — астраханские казаки","d":"Астраханские казаки носили жёлтый лампас, и на смотрах по волжскому берегу их сотни узнавали по этому цвету ещё издали.","href":"/muzei/narodnyy-kostyum/den/08-22/"},"08-23":{"t":"Кунгур — праздничный наряд Пермской губ.","d":"Кунгурские кожевники шили сапоги на всю Сибирь, и на праздник парень надевал сапоги со скрипом, чтобы его слышало всё село.","href":"/muzei/narodnyy-kostyum/den/08-23/"},"08-24":{"t":"Солигалич — праздничный наряд солеваренного посада","d":"Солигалич веками жил солеварением, и купчихи посада на праздник выходили в штофных сарафанах, купленных на деньги от соляных варниц.","href":"/muzei/narodnyy-kostyum/den/08-24/"},"08-25":{"t":"Костромская обл., 1960-е — бабушкин сундук","d":"Костромская бабушка в 1960-е хранила в сундуке и прабабкин сарафан, и новое штапельное платье, купленное в сельпо к Первомаю.","href":"/muzei/narodnyy-kostyum/den/08-25/"},"08-26":{"t":"Суздаль — владимирские наряды в музее","d":"Владимирский сарафан пролежал в суздальских фондах больше века, а его кумачовая краска до сих пор не выцвела, потому что красили мареной.","href":"/muzei/narodnyy-kostyum/den/08-26/"},"08-27":{"t":"Пензенская губ. — жатва: жницы в поле","d":"Пензенская жница выходила в поле в самой простой рубахе, а последний сноп, дожинок, несла домой в лучшем платке и с песней.","href":"/muzei/narodnyy-kostyum/den/08-27/"},"08-28":{"t":"Москва, посад — посадские люди XVII в. по описям имущества","d":"По описям имущества московского посадского можно пересчитать каждый зипун и телогрею, ведь одежду тогда записывали наравне с деньгами.","href":"/muzei/narodnyy-kostyum/den/08-28/"},"08-29":{"t":"Москва, коронация 1883 — депутации крестьян на коронации Александра III","d":"На коронацию Александра III в 1883 году волостные старшины приехали в Москву в лучших кафтанах, с бляхой на груди и хлебом-солью на рушнике.","href":"/muzei/narodnyy-kostyum/den/08-29/"},"08-30":{"t":"Москва, подмастерья — мальчики-ученики в мастерской","d":"Московского мальчика отдавали в ученье лет в десять, и первые годы он донашивал хозяйские обноски, бегая по поручениям с утра до ночи.","href":"/muzei/narodnyy-kostyum/den/08-30/"},"08-31":{"t":"Орловская губ., Мценский уезд, усадьба — барыня и дворовые","d":"В Спасском-Лутовинове мать Тургенева одевала дворовых по своему вкусу, и казачок при барыне носил ливрейный кафтанчик даже в летний зной.","href":"/muzei/narodnyy-kostyum/den/08-31/"},"09-01":{"t":"Витебская губ. — праздничный наряд Поозерья","d":"Поозерская девушка ткала себе андарак в красную полоску к первой ярмарке, и по этой полоске сваты узнавали её мастерство издалека.","href":"/muzei/narodnyy-kostyum/den/09-01/"},"09-02":{"t":"Лебедянь — праздничный наряд Лебедянского уезда","d":"Лебедянская понёва переходила от матери к дочери вместе с правом носить её только после свадьбы, и девушка ждала этого дня годами.","href":"/muzei/narodnyy-kostyum/den/09-02/"},"09-03":{"t":"Моршанский уезд Тамбовской губ. — свадьба","d":"Моршанская невеста в день свадьбы трижды меняла наряд, и последний, бабий, надевали на неё уже в доме жениха.","href":"/muzei/narodnyy-kostyum/den/09-03/"},"09-04":{"t":"Калязин — шапочницы и кокошницы","d":"Калязинская кокошница неделями вышивала один кокошник речным жемчугом, а заказчица носила его потом всю жизнь и отдавала дочери.","href":"/muzei/narodnyy-kostyum/den/09-04/"},"09-05":{"t":"Некрасовцы — возвращение 1962 года","d":"В 1962 году некрасовцы после двух веков в Турции вернулись на Ставрополье и привезли в сундуках платья, сшитые ещё по донскому крою.","href":"/muzei/narodnyy-kostyum/den/09-05/"},"09-06":{"t":"Чердынь — одежда северного Урала","d":"Чердынский охотник уходил в парму на всю зиму в лузане, наплечнике из сукна, где за спиной помещалась вся добыча и запас еды.","href":"/muzei/narodnyy-kostyum/den/09-06/"},"09-07":{"t":"Сольвычегодск — строгановское шитьё и крестьянский наряд","d":"В светлицах Строгановых в Сольвычегодске золотошвеи вышивали пелены шёлком так тонко, что лица святых выглядели написанными кистью.","href":"/muzei/narodnyy-kostyum/den/09-07/"},"09-08":{"t":"Москва, извозчики — синий кафтан и кушак извозчика","d":"Московский лихач подбивал синий кафтан ватой так толсто, что седок видел перед собой широкую спину, будто у богатыря.","href":"/muzei/narodnyy-kostyum/den/09-08/"},"09-09":{"t":"Ветлужский уезд Костромской губ. — по грибы и ягоды: лесная одежда","d":"Ветлужские бабы ходили в лес в самом старом сарафане, а лучший берегли до праздника, и по лесной одежде можно прочесть всю её жизнь.","href":"/muzei/narodnyy-kostyum/den/09-09/"},"09-10":{"t":"Нижний Тагил — заводские мастеровые Урала","d":"Тагильский доменщик надевал войлочную шляпу с широкими полями, и она спасала лицо от искр у раскалённой печи лучше любой каски.","href":"/muzei/narodnyy-kostyum/den/09-10/"},"09-11":{"t":"Алтай, 1954 — целина","d":"Весной 1954 года первые целинники приехали в алтайскую степь в ватниках и кирзе, и палатки стояли посреди снега ещё несколько недель.","href":"/muzei/narodnyy-kostyum/den/09-11/"},"09-12":{"t":"Переславль-Залесский, музей — спасённые сарафаны","d":"Переславский музей собирал сарафаны по окрестным сёлам, когда их уже пускали на тряпки, и сберёг штофные наряды, сшитые ещё при Екатерине.","href":"/muzei/narodnyy-kostyum/den/09-12/"},"09-13":{"t":"Нижний Ломов, Пензенская губ. — прядение шерсти","d":"Пензенская пряха за осенний вечер на посиделках выпрядала моток шерсти, и из таких мотков к весне складывалась вся зимняя одежда семьи.","href":"/muzei/narodnyy-kostyum/den/09-13/"},"09-14":{"t":"Кирсановский уезд Тамбовской губ. — Семёнов день: постриги и посажение мальчика на коня","d":"На Семёнов день тамбовскому мальчику впервые стригли волосы и сажали на коня, и с этого дня он носил рубаху с отцовским поясом.","href":"/muzei/narodnyy-kostyum/den/09-14/"},"09-15":{"t":"Хопёр — хопёрские казаки","d":"Хопёрская казачка надевала шлычку сразу после венчания и больше никогда не показывалась на людях с непокрытыми волосами.","href":"/muzei/narodnyy-kostyum/den/09-15/"},"09-16":{"t":"Ливны, Орловская губ. — купеческий и крестьянский праздничный наряд","d":"В Ливнах на ярмарку купчиха и крестьянка выходили рядом, и одна покупала у другой домотканую понёву за цену шёлкового платья.","href":"/muzei/narodnyy-kostyum/den/09-16/"},"09-17":{"t":"Буй, Костромская губ. — сундук невесты: приданое","d":"Буйская невеста с детства копила приданое в окованном сундуке, и на смотринах сваха пересчитывала рубахи и полотенца на глазах у жениховой родни.","href":"/muzei/narodnyy-kostyum/den/09-17/"},"09-18":{"t":"Белозерье — «сороки» и белозерский женский убор","d":"Белозерская молодуха не снимала сороку даже в поле, потому что показаться простоволосой считалось для замужней тяжким позором.","href":"/muzei/narodnyy-kostyum/den/09-18/"},"09-19":{"t":"Петербург, кормилицы — кормилица в «русском» кокошнике","d":"Петербургская барыня заказывала кормилице кокошник и сарафан нарочно, и по Невскому та гуляла с младенцем, как живая вывеска богатого дома.","href":"/muzei/narodnyy-kostyum/den/09-19/"},"09-20":{"t":"Гродненская губ. — праздничный наряд Понёманья","d":"Понёманская молодуха наматывала намитку из длинного белёного полотна так ловко, что узел нельзя было повторить без бабкиного урока.","href":"/muzei/narodnyy-kostyum/den/09-20/"},"09-21":{"t":"Нарым, Томская губ. — детская одежда сибирских старожилов","d":"Нарымские старожилы шили младенцу меховой мешок, перенятый у соседей-остяков, и в нём ребёнок переживал сорокаградусный мороз в санях.","href":"/muzei/narodnyy-kostyum/den/09-21/"},"09-22":{"t":"Шадринск — праздничный наряд Зауралья","d":"Шадринская невеста получала в приданое штофный сарафан, привезённый с Ирбитской ярмарки, и носила его до самой старости по большим праздникам.","href":"/muzei/narodnyy-kostyum/den/09-22/"},"09-23":{"t":"Дорогобуж — отставной солдат в деревне","d":"Отставной солдат возвращался в Дорогобужский уезд после двадцати пяти лет службы и носил старую шинель с медалью до самой смерти.","href":"/muzei/narodnyy-kostyum/den/09-23/"},"09-24":{"t":"Русское Устье, Индигирка — метель: одежда русскоустьинцев","d":"Русскоустьинцы на Индигирке жили у Ледовитого океана с XVII века и в пургу носили оленьи парки, сохранив при этом старинный русский говор.","href":"/muzei/narodnyy-kostyum/den/09-24/"},"09-25":{"t":"Ярославль — одежда XVII века по фрескам и описям","d":"На фресках ярославских храмов мастера XVII века одели библейских героев в кафтаны и летники посадских людей, и по ним изучают одежду той поры.","href":"/muzei/narodnyy-kostyum/den/09-25/"},"09-26":{"t":"Петербург, ассамблеи — указ об ассамблеях 1718 года","d":"По указу 1718 года петербургские купцы являлись на ассамблеи в немецком платье, и жёны их впервые танцевали на людях без покрывала на волосах.","href":"/muzei/narodnyy-kostyum/den/09-26/"},"09-27":{"t":"Клинцы — суконщики-старообрядцы","d":"Клинцовские старообрядцы ткали сукно, из которого шили кафтаны и армяки по всей России, и к концу XIX века их слободу звали русским Манчестером.","href":"/muzei/narodnyy-kostyum/den/09-27/"},"09-28":{"t":"Ставрополь, Кавказская линия — свадьба линейного казака","d":"Линейный казак Кавказской линии венчался при шашке и кинжале, и даже на собственной свадьбе он не расставался с оружием, без которого не выезжал за станицу.","href":"/muzei/narodnyy-kostyum/den/09-28/"},"09-29":{"t":"Тихвин — тихвинский праздничный наряд","d":"На Тихвинскую ярмарку девушки съезжались в лучших сарафанах с позументом, и здесь же матери присматривали им женихов среди купеческих сыновей.","href":"/muzei/narodnyy-kostyum/den/09-29/"},"09-30":{"t":"Москва, ВСХВ 1939 — колхозницы в праздничных нарядах на выставке","d":"Летом 1939 года лучшие колхозницы приехали на открытие ВСХВ в Москве в вышитых блузах, сшитых по народным образцам специально к выставке.","href":"/muzei/narodnyy-kostyum/den/09-30/"},"10-01":{"t":"Ялуторовск — сибирские сарафаны в музее","d":"Сибирский штофный сарафан из ялуторовского сундука пережил ссыльных декабристов, живших в городе, и попал в музей почти без потёртостей.","href":"/muzei/narodnyy-kostyum/den/10-01/"},"10-02":{"t":"Болхов — праздничный наряд Болховского уезда","d":"Болховская молодуха прятала волосы под рогатую кичку, и священники зря боролись с «рогами» — убор носили до конца века.","href":"/muzei/narodnyy-kostyum/den/10-02/"},"10-03":{"t":"Выг — свадьба у поморских старообрядцев","d":"На Выге беспоповцы венчались без попа, и невеста шла к общей молитве в тёмном сарафане, будто на службу, а не на пир.","href":"/muzei/narodnyy-kostyum/den/10-03/"},"10-04":{"t":"Ишим — праздничный наряд сибирячек","d":"На Никольскую ярмарку в Ишиме сибирячки приезжали в парчовых сарафанах, и привозной китайский шёлк шёл на них наравне с московским.","href":"/muzei/narodnyy-kostyum/den/10-04/"},"10-05":{"t":"Казань — студенты и курсистки 1870-х","d":"Казанская курсистка 1870-х нарочно стригла волосы и носила тёмное платье без кружев, и полиция видела в этом почти политический знак.","href":"/muzei/narodnyy-kostyum/den/10-05/"},"10-06":{"t":"Виленская губ. — белорусская крестьянская одежда","d":"Виленская баба ткала андарак сама, и полосы на юбке сразу выдавали соседкам, из какой она деревни и какого рода.","href":"/muzei/narodnyy-kostyum/den/10-06/"},"10-07":{"t":"Лешуконье — «рядовая» будничная одежда: пестрядь и льняной сарафан","d":"Лешуконский пестрядинный сарафан носили до дыр, и, затёртый до сплошных заплат, он дожил до экспедиции почти без следа праздника.","href":"/muzei/narodnyy-kostyum/den/10-07/"},"10-08":{"t":"Крестцы — мастерицы крестецкой строчки","d":"Крестецкие мастерицы выдёргивали нити из полотна и превращали холст в кружевную решётку, а их строчку возили на выставку в Париж.","href":"/muzei/narodnyy-kostyum/den/10-08/"},"10-09":{"t":"Усть-Медведицкая — казачата: посажение на коня","d":"Казачонка Усть-Медведицкой станицы в год от роду сажали на коня в папахе, и по тому, как он хватал гриву, родня гадала о судьбе.","href":"/muzei/narodnyy-kostyum/den/10-09/"},"10-10":{"t":"Устюжна — лён: трепание и мятьё","d":"Устюжские бабы трепали лён на осенних сборищах до темноты, и вся будничная одежда семьи начиналась с этой серой кострицы в волосах.","href":"/muzei/narodnyy-kostyum/den/10-10/"},"10-11":{"t":"Брянские леса — дегтяри и углежоги","d":"Брянского дегтяря узнавали в любой деревне за версту по запаху, и его сермяга, пропитанная дёгтем, годами не пропускала дождя.","href":"/muzei/narodnyy-kostyum/den/10-11/"},"10-12":{"t":"Тара — сибирские старожилы","d":"Тарские старожилы держались своих сарафанов с позументом и посмеивались над новыми переселенцами, которых звали «самоходами».","href":"/muzei/narodnyy-kostyum/den/10-12/"},"10-13":{"t":"Жиздра — понёвный наряд на границе средней полосы","d":"В жиздринских сёлах понёва и сарафан встречались на одной улице, и по юбке соседки сразу понимали, чья невестка пришла из какой деревни.","href":"/muzei/narodnyy-kostyum/den/10-13/"},"10-14":{"t":"Плёс, Покров — Покров: начало свадеб, наряд невесты","d":"На Покров плёсские девушки молились «Покров-батюшка, покрой землю снежком, а меня женишком», и с этого дня невесты шили венчальный сарафан.","href":"/muzei/narodnyy-kostyum/den/10-14/"},"10-15":{"t":"Данков — свадьба","d":"Данковской невесте на свадьбе расплетали девичью косу на две, и с этой минуты её волосы под кичкой мог видеть только муж.","href":"/muzei/narodnyy-kostyum/den/10-15/"},"10-16":{"t":"Лальск — ученики земской школы","d":"Лальские школьники ходили в земскую школу за несколько вёрст в лаптях и несли книги в холщовой сумке, сшитой матерью из старого сарафана.","href":"/muzei/narodnyy-kostyum/den/10-16/"},"10-17":{"t":"Ачинск, клуб — сельская самодеятельность 1930-х в старых нарядах","d":"В 1930-е сельский хор под Ачинском выходил на сцену клуба в бабушкиных сарафанах, и вещи, спрятанные в сундуки, снова оказались на виду.","href":"/muzei/narodnyy-kostyum/den/10-17/"},"10-18":{"t":"Кадом, сегодня — мастерицы продолжают кадомскую вязь","d":"Кадомскую вязь когда-то плели всем посадом, и сегодня кружево по старым сколкам вяжут в Кадоме снова, чтобы узор не пропал.","href":"/muzei/narodnyy-kostyum/den/10-18/"},"10-19":{"t":"Кенозеро — праздничный наряд у часовен","d":"В кенозерские престольные праздники к деревянным часовням шли в лучших сарафанах, и многие из этих часовен стоят у озера до сих пор.","href":"/muzei/narodnyy-kostyum/den/10-19/"},"10-20":{"t":"Урюпинская — пуховый платок","d":"Хопёрские казачки вязали пуховые платки из козьего пуха, и в Урюпинске козе даже поставили памятник за то, что кормила станицу.","href":"/muzei/narodnyy-kostyum/den/10-20/"},"10-21":{"t":"Кизляр — казачья вдова и старуха","d":"Кизлярская казачья вдова снимала яркие ленты навсегда, и чёрный платок она носила до самой смерти, сколько бы лет ни прошло.","href":"/muzei/narodnyy-kostyum/den/10-21/"},"10-22":{"t":"Ферапонтово — одежды людей на фресках Дионисия","d":"Дионисий с сыновьями расписал собор Ферапонтова монастыря летом 1502 года, и одежды людей на его фресках до сих пор светятся красками из местных камней.","href":"/muzei/narodnyy-kostyum/den/10-22/"},"10-23":{"t":"Гатчина — Павел I: указы об одежде 1797–1800","d":"Павел I запретил в столице круглые шляпы и фраки, и полиция прямо на улице срывала с прохожих «якобинские» шляпы.","href":"/muzei/narodnyy-kostyum/den/10-23/"},"10-24":{"t":"Илимск — старожилы-чалдоны","d":"Илимские чалдоны жили на Ангаре со времён острогов и свой старинный сарафан с позументом считали знаком коренного сибиряка.","href":"/muzei/narodnyy-kostyum/den/10-24/"},"10-25":{"t":"Печора, охота — зимний охотничий наряд","d":"Печорский охотник уходил в тайгу на всю зиму в малице, перенятой у соседей-ненцев, и без неё в лесу не прожил бы и недели.","href":"/muzei/narodnyy-kostyum/den/10-25/"},"10-26":{"t":"Саратов — портные ремесленной слободы","d":"Саратовский портной-самоучка шил сюртук «как в столице» по картинке из журнала, и мещане заказывали у него одежду к Пасхе за полгода.","href":"/muzei/narodnyy-kostyum/den/10-26/"},"10-27":{"t":"Витебская губ., Дзяды — Дзяды: поминальная одежда","d":"На осенние Дзяды витебская хозяйка ставила на стол ложки для умерших предков, а сама надевала белую намитку, как на похоронах.","href":"/muzei/narodnyy-kostyum/den/10-27/"},"10-28":{"t":"Брянск — праздничный наряд Брянского уезда","d":"Брянская понёва с бархатной полосой по подолу была главным богатством молодухи, и её передавали дочери вместе с сундуком.","href":"/muzei/narodnyy-kostyum/den/10-28/"},"10-29":{"t":"Якутск — свадьба ленских старожилов","d":"На свадьбе ленских старожилов в Якутске невеста ехала к венцу в шубе поверх штофного сарафана, потому что зимой мороз доходил до пятидесяти.","href":"/muzei/narodnyy-kostyum/den/10-29/"},"10-30":{"t":"Берёзов — охотник-промысловик","d":"Берёзовские промысловики сдавали казне ясак соболем, и одна удачная зима в тайге могла одеть всю семью в новое сукно.","href":"/muzei/narodnyy-kostyum/den/10-30/"},"10-31":{"t":"Сумский посад — шугай и праздничный наряд поморок","d":"Жёны сумских поморов надевали парчовый шугай с жемчужным кокошником, когда мужья возвращались с Мурмана, и весь посад выходил на берег.","href":"/muzei/narodnyy-kostyum/den/10-31/"},"11-01":{"t":"Териберка — поморы в рыболовецких колхозах","d":"В териберском колхозе помор надевал на путину тот же просмолённый рокан, что и его дед, только улов теперь сдавали по колхозной квитанции.","href":"/muzei/narodnyy-kostyum/den/11-01/"},"11-02":{"t":"Рыбинск, музей — наряды Ярославской губ. в собрании","d":"Рыбинский музей принял на хранение сундуки волжских купчих, и штофные сарафаны оттуда пережили сам купеческий город на Волге.","href":"/muzei/narodnyy-kostyum/den/11-02/"},"11-03":{"t":"Бухтарма (Алтай) — каменщики-старообрядцы","d":"Бухтарминские каменщики ушли от властей в горы Алтая и сотню лет шили одежду только сами, не подпуская к своим сундукам ни одного чужака.","href":"/muzei/narodnyy-kostyum/den/11-03/"},"11-04":{"t":"Весьегонск — Казанская осенняя: праздничный выход","d":"На осеннюю Казанскую весьегонские бабы выходили к обедне в шушунах поверх сарафанов, потому что в ноябре по Мологе уже шёл первый лёд.","href":"/muzei/narodnyy-kostyum/den/11-04/"},"11-05":{"t":"Кукарка (Вятская губ.) — вятское кружево","d":"Кукарские кружевницы плели на коклюшках тонкую сцепную ленту, и эти кружева уходили от вятской слободы на ярмарки до самого Петербурга.","href":"/muzei/narodnyy-kostyum/den/11-05/"},"11-06":{"t":"Новочеркасск — атаманский наряд и регалии","d":"Новочеркасский атаман принимал от станиц насеку и булаву, а чекмень с галуном шился так, чтобы его было видно с другого конца майдана.","href":"/muzei/narodnyy-kostyum/den/11-06/"},"11-07":{"t":"Любим — парни-женихи на беседе","d":"Любимский парень приходил на осеннюю беседу в сапогах гармошкой и с часами на цепочке, и серебряная цепочка поверх жилета говорила девкам о женихе больше любых слов.","href":"/muzei/narodnyy-kostyum/den/11-07/"},"11-08":{"t":"Вязьма — армяк и епанча в непогоду","d":"В смоленском распутье ямщик из Вязьмы набрасывал поверх армяка широкую епанчу, и дождь стекал с неё, не доходя до тулупа.","href":"/muzei/narodnyy-kostyum/den/11-08/"},"11-09":{"t":"Грязовец — праздничная одежда Грязовецкого уезда","d":"Грязовецкая невеста ткала себе браную рубаху всю зиму, и узор на рукаве у каждой деревни уезда был свой, как роспись под документом.","href":"/muzei/narodnyy-kostyum/den/11-09/"},"11-10":{"t":"Инсар (Пензенская губ.) — русский наряд Пензенской губ.","d":"В инсарских сёлах понёву в синюю клетку надевали только замужние, и девушка впервые запахивала её на себе в день свадьбы.","href":"/muzei/narodnyy-kostyum/den/11-10/"},"11-11":{"t":"Мещовск (Калужская губ.) — жених и его наряд","d":"Мещовский жених ехал к венцу, подпоясанный кушаком, который невеста ткала ему сама, и по этому кушаку вся деревня судила о её руках.","href":"/muzei/narodnyy-kostyum/den/11-11/"},"11-12":{"t":"Стародуб — стародубские старообрядцы","d":"Стародубские слободы старообрядцев держали старый покрой кафтана два века подряд, и в их сундуках он сохранился почти таким же, как при царе Алексее.","href":"/muzei/narodnyy-kostyum/den/11-12/"},"11-13":{"t":"Кола — портовый город: русские и иностранцы","d":"В порту Колы помор в кафтане и норвежец в зюйдвестке торговались на смешанном языке руссенорск, и одежда обоих пахла одной и той же треской.","href":"/muzei/narodnyy-kostyum/den/11-13/"},"11-14":{"t":"Краснослободск — Кузьминки: девичий осенний праздник","d":"На Кузьминки девушки сами варили кашу и звали парней на складчину, а лучший сарафан берегли именно к этому осеннему вечеру.","href":"/muzei/narodnyy-kostyum/den/11-14/"},"11-15":{"t":"Гомельщина — праздничный наряд Посожья","d":"На берегах Сожа намитка замужней женщины была длиной в несколько локтей, и наматывали её так ловко, что концы ложились точно на спину.","href":"/muzei/narodnyy-kostyum/den/11-15/"},"11-16":{"t":"Коротояк — мужской праздничный наряд: свита и вышитая рубаха","d":"Коротоякский мужик шёл на престольный праздник в белой свите, и вышивку на его рубахе видели только тогда, когда он распахивал полы в церкви.","href":"/muzei/narodnyy-kostyum/den/11-16/"},"11-17":{"t":"Бронницкий уезд — шёлкоткацкие светёлки","d":"В подмосковных светёлках девки ткали шёлк для городских лавок, а сами носили ситец и надевали шёлковый платок только к венцу.","href":"/muzei/narodnyy-kostyum/den/11-17/"},"11-18":{"t":"Тамань — черноморские казаки, наследники запорожцев","d":"Черноморские казаки высадились на Тамани в 1792 году ещё в запорожских кунтушах, но уже через одно поколение все носили черкески.","href":"/muzei/narodnyy-kostyum/den/11-18/"},"11-19":{"t":"Козельск, 1920-е — лапти уходят: фабричная обувь в деревне","d":"В козельских деревнях двадцатых годов лапти ещё плели каждую зиму, но к свадьбе жених уже покупал фабричные сапоги с калошами.","href":"/muzei/narodnyy-kostyum/den/11-19/"},"11-20":{"t":"Глазов — Дмитрий Зеленин, этнограф Вятской губ., и его записи","d":"Молодой Дмитрий Зеленин объезжал вятские сёла с тетрадкой и записывал, кто что носит, и его описания вятской одежды цитируют этнографы до сих пор.","href":"/muzei/narodnyy-kostyum/den/11-20/"},"11-21":{"t":"Москва — глазами иностранцев: Герберштейн и Олеарий на улицах XVI–XVII вв.","d":"Барон Герберштейн подробно описал длинные московские кафтаны с рукавами до пят, и его гравюры стали первым портретом русского костюма для Европы.","href":"/muzei/narodnyy-kostyum/den/11-21/"},"11-22":{"t":"Петербург — конюшенный двор: придворный кучер и скороход в «русском» платье","d":"Придворного кучера в Петербурге нарочно подбивали ватой, чтобы на козлах он выглядел дородным русским мужиком, как того требовал этикет двора.","href":"/muzei/narodnyy-kostyum/den/11-22/"},"11-23":{"t":"Череповец — праздничный наряд Череповецкого уезда","d":"Череповецкие крестьянки выходили на праздник в шугаях из покупной парчи, хотя сарафан под ним был соткан дома из своего льна.","href":"/muzei/narodnyy-kostyum/den/11-23/"},"11-24":{"t":"Унжа — весенний сплав: одежда сплавщиков","d":"Унженские сплавщики шли за плотами в высоких бахилах, промазанных дёгтем, и неделями не снимали их, пока лес не доходил до Волги.","href":"/muzei/narodnyy-kostyum/den/11-24/"},"11-25":{"t":"Кежма (Ангара) — ангарские старожилы","d":"Ангарские старожилы Кежмы получали ткани с купеческих барок раз в лето, и шёлковый платок на праздник мог прослужить в семье три поколения.","href":"/muzei/narodnyy-kostyum/den/11-25/"},"11-26":{"t":"Усмань (Тамбовская губ.) — праздничный наряд Усманского уезда","d":"В усманских сёлах замужние носили рогатую кичку, и священники долго и без толку уговаривали баб снимать её хотя бы перед причастием.","href":"/muzei/narodnyy-kostyum/den/11-26/"},"11-27":{"t":"Ковда — поморская свадьба","d":"Ковдская невеста шла к венцу в жемчужной повязке, взятой у богатой родни, и после свадьбы повязку честно возвращали хозяйке.","href":"/muzei/narodnyy-kostyum/den/11-27/"},"11-28":{"t":"Рославль — детские обереги в одежде","d":"Первую рубашку рославльскому младенцу шили из старой отцовской, веря, что ношеное полотно надёжнее нового защищает ребёнка от сглаза.","href":"/muzei/narodnyy-kostyum/den/11-28/"},"11-29":{"t":"Красные Баки — нижегородский гипюр","d":"Краснобаковские мастерицы вышивали гипюр по вырезанной сетке, и одну скатерть такого узора девушка могла делать всю зиму подряд.","href":"/muzei/narodnyy-kostyum/den/11-29/"},"11-30":{"t":"Волжское войско — волжские казаки","d":"Волжское казачье войско продержалось меньше полувека, и его кафтаны остались почти только в описях, а казаков переселили на Кавказ.","href":"/muzei/narodnyy-kostyum/den/11-30/"},"12-01":{"t":"Астрахань — торг","d":"Астраханский рыботорговец ехал на ярмарку в овчинном тулупе, а под ним прятал суконный кафтан, чтобы на торгу выглядеть хозяином.","href":"/muzei/narodnyy-kostyum/den/12-01/"},"12-02":{"t":"Верхняя Тойма — девичья одежда на зимних посиделках","d":"На тоемские посиделки девушка приносила расписную прялку и надевала лучший сарафан, потому что там же её высматривали женихи.","href":"/muzei/narodnyy-kostyum/den/12-02/"},"12-03":{"t":"Новогрудок — белорусская свадьба","d":"Новогрудскую невесту перед венчанием покрывали намиткой, и с этого белого полотна начиналась вся её жизнь замужней женщины.","href":"/muzei/narodnyy-kostyum/den/12-03/"},"12-04":{"t":"Туринск — сибиряк-старожил: зипун и шуба","d":"Туринский старожил носил одну шубу по сорок зим, и в его завещании она стояла сразу после избы и коровы.","href":"/muzei/narodnyy-kostyum/den/12-04/"},"12-05":{"t":"Братск, Ангара — ангарский наряд","d":"Старый Братск ушёл под воду Братского водохранилища в начале 1960-х, и ангарские наряды его жителей уцелели лишь в сундуках переселенцев и музейных сборах.","href":"/muzei/narodnyy-kostyum/den/12-05/"},"12-06":{"t":"Киров, 1941–1945 — вязаные рукавицы фронту","d":"Вятские школьницы вязали фронту трёхпалые рукавицы с отдельным указательным пальцем, чтобы боец мог стрелять, не снимая их.","href":"/muzei/narodnyy-kostyum/den/12-06/"},"12-07":{"t":"Вязники, Катерина — Катерина-санница: катание в санях","d":"На Катерину-санницу вязниковские парни впервые выезжали на санях с горы, и девушка в шубке решала, к кому сесть.","href":"/muzei/narodnyy-kostyum/den/12-07/"},"12-08":{"t":"Обоянь, коллекция — курская вышивка в музее","d":"Обоянская рубаха с красной вышивкой пролежала в сундуке три поколения, прежде чем её передали в музей вместе с понёвой.","href":"/muzei/narodnyy-kostyum/den/12-08/"},"12-09":{"t":"Чудское озеро — подлёдный лов","d":"Чудские рыбаки уходили на лёд артелью по двадцать человек, и в непогоду тулуп спасал жизнь надёжнее любой молитвы.","href":"/muzei/narodnyy-kostyum/den/12-09/"},"12-10":{"t":"Пронск — праздничный наряд Пронского уезда","d":"Пронская молодуха носила рогатую кичку, и священники долго гоняли её за эти рога, но обычай всё равно пережил запреты.","href":"/muzei/narodnyy-kostyum/den/12-10/"},"12-11":{"t":"Покров (Владимирская губ.) — мать семьи «большуха»: одежда хозяйки дома","d":"Большуха носила на поясе ключи от всех клетей, и невестки по одному звону этой связки знали, что хозяйка уже встала.","href":"/muzei/narodnyy-kostyum/den/12-11/"},"12-12":{"t":"Колывань — сибирское ткачество","d":"Колыванские ткачихи ставили кросна в избе на всю зиму, и к весне из них выходило полотна на одежду всей большой семьи.","href":"/muzei/narodnyy-kostyum/den/12-12/"},"12-13":{"t":"Красноярск — енисейские казаки","d":"Енисейские казаки несли службу на краю империи, и жёлтый лампас на их шароварах видели в тайге за сотни вёрст от любого города.","href":"/muzei/narodnyy-kostyum/den/12-13/"},"12-14":{"t":"Повенец — лесорубы и сплавщики Повенецкого уезда","d":"Повенецкий сплавщик стоял на бревне в высоких бахилах неделями подряд, и ноги у него оставались сухими только благодаря дёгтю.","href":"/muzei/narodnyy-kostyum/den/12-14/"},"12-15":{"t":"Стародубье — старообрядческие слободы","d":"Стародубские слободы приняли беглецов-старообрядцев, и те держали покрой сарафана неизменным почти два века.","href":"/muzei/narodnyy-kostyum/den/12-15/"},"12-16":{"t":"Верхотурье XVII в. — одежда торговых людей по таможенным книгам и описям","d":"Через верхотурскую таможню шли все товары в Сибирь, и подьячие вписывали в книги даже сукно на кафтане проезжего купца.","href":"/muzei/narodnyy-kostyum/den/12-16/"},"12-17":{"t":"Петербург, двор Александра III — «русский стиль» при дворе","d":"При Александре III придворные дамы являлись на большой выход в сарафанах и кокошниках, и это было обязательно по уставу двора.","href":"/muzei/narodnyy-kostyum/den/12-17/"},"12-18":{"t":"Балахна — детский наряд купеческой семьи","d":"Балахнинский купеческий сын получал первую поддёвку к семи годам, и с этого дня отец брал его с собой в лавку.","href":"/muzei/narodnyy-kostyum/den/12-18/"},"12-19":{"t":"Старая Русса, Никола — Никола зимний: зимний праздничный выход","d":"На Николу зимнего старорусские мужики шли в церковь в новых поддёвках, а после службы начинались братчины на всю деревню.","href":"/muzei/narodnyy-kostyum/den/12-19/"},"12-20":{"t":"Симбирск — русское купечество","d":"Симбирские купчихи выходили на соборную площадь в турецких шалях, и цена одной такой шали равнялась цене доброго дома.","href":"/muzei/narodnyy-kostyum/den/12-20/"},"12-21":{"t":"Валуйки — украинские слободы Воронежской губ.","d":"Валуйские слободы держали малороссийскую плахту два столетия, хотя рядом в соседних сёлах уже носили русскую понёву.","href":"/muzei/narodnyy-kostyum/den/12-21/"},"12-22":{"t":"Козлов — косцы: мужской покосный наряд","d":"Козловские косцы выходили на покос в белых рубахах, и к вечеру по пятнам пота на холсте было видно, кто в артели работал лучше.","href":"/muzei/narodnyy-kostyum/den/12-22/"},"12-23":{"t":"Борисоглебск, 1917 — солдатская шинель приходит в деревню","d":"Солдаты, вернувшиеся в борисоглебские сёла в 1917-м, донашивали шинели годами, а потом из них шили детям пальто.","href":"/muzei/narodnyy-kostyum/den/12-23/"},"12-24":{"t":"Тамбов, сегодня — центр народной культуры: шьют по образцу","d":"Тамбовские мастерицы шьют понёву по образцу из экспедиции, и каждую клетку проверяют по старому снимку прежде, чем ткать.","href":"/muzei/narodnyy-kostyum/den/12-24/"},"12-25":{"t":"Олёкминск — зимняя одежда русских старожилов","d":"Олёкминские старожилы переняли у якутов меховые торбаса, потому что в морозы за пятьдесят русские валенки не спасали.","href":"/muzei/narodnyy-kostyum/den/12-25/"},"12-26":{"t":"Белёв — праздничный наряд Белёвского уезда","d":"Белёвская молодуха вшивала в рукав рубахи полосу кумача, и по ширине этой полосы соседки судили о достатке её семьи.","href":"/muzei/narodnyy-kostyum/den/12-26/"},"12-27":{"t":"Уржум — свадьба","d":"Уржумская невеста плакала на свадьбе по обычаю три дня, и её свадебный венец девушки потом разбирали на ленты на счастье.","href":"/muzei/narodnyy-kostyum/den/12-27/"},"12-28":{"t":"Елатьма — красное ткачество","d":"Елатомские ткачихи окрашивали нитку марёной в густой красный цвет, и полотенца из этой нитки не линяли даже через сто лет.","href":"/muzei/narodnyy-kostyum/den/12-28/"},"12-29":{"t":"Раздорская — казачий курень: будничная одежда","d":"Раздорская казачка носила кубелёк и дома, и на базу, потому что в курене, где мужья годами были в походах, хозяйкой была она.","href":"/muzei/narodnyy-kostyum/den/12-29/"},"12-30":{"t":"Красноборск — праздничный наряд","d":"Красноборская девушка ходила на гулянье в штофном сарафане, который мать купила на ярмарке в Сольвычегодске за целый воз льна.","href":"/muzei/narodnyy-kostyum/den/12-30/"},"12-31":{"t":"Ветка — старообрядцы Ветки","d":"Ветковские старообрядцы дважды пережили выгонку войсками, но их сарафаны и кики сохранились в музее Ветки до сих пор.","href":"/muzei/narodnyy-kostyum/den/12-31/"}};
